<?php
namespace Tests\Feature;use App\Models\{AccessPoint,Institution,User};use Database\Seeders\{ApLoadThresholdSeeder,RolesAndPermissionsSeeder,SystemThresholdSeeder};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class AccessPointLoadTest extends TestCase{use RefreshDatabase;protected function setUp():void{parent::setUp();$this->seed([RolesAndPermissionsSeeder::class,SystemThresholdSeeder::class,ApLoadThresholdSeeder::class]);}private function context():array{$u=User::factory()->create();$u->assignRole('Network Admin');$i=Institution::create(['name'=>'T','slug'=>'t']);$c=$i->campuses()->create(['name'=>'M','code'=>'M']);$b=$c->buildings()->create(['name'=>'B','code'=>'B']);$f=$b->floors()->create(['name'=>'G','code'=>'G','level_number'=>0]);$ap=AccessPoint::create(['floor_id'=>$f->id,'name'=>'AP-01','identifier'=>'AP-01','configured_client_limit'=>50]);return[$u,$ap];}public function test_high_load_with_degraded_performance_is_possible_congestion():void{[$u,$ap]=$this->context();$ap->loadSamples()->create(['connected_clients'=>80,'channel_utilisation_percent'=>85,'latency_ms'=>130,'packet_loss_percent'=>4,'throughput_mbps'=>7,'source_type'=>'controller','sampled_at'=>now()]);$this->actingAs($u)->getJson("/api/access-points/{$ap->id}/analysis")->assertOk()->assertJson(['classification'=>'possible_congestion','rule'=>'LOAD-001']);}public function test_missing_telemetry_returns_insufficient_evidence():void{[$u,$ap]=$this->context();$this->actingAs($u)->getJson("/api/access-points/{$ap->id}/analysis")->assertOk()->assertJson(['classification'=>'insufficient_evidence']);}}
